tool_input.command:
cat > sim.tmp.cjs <<'EOF'
// Stand-in for the kit: ticks at k/30, host reads depth every 3 ticks, new level seen on the following tick.
const fs = require("fs");
const src = fs.readFileSync("game.package.js", "utf8");
const step = new Function(src.slice(src.indexOf("const IDLE"), src.indexOf("export const gameRuntime")).replace("export function", "function") + "return gameStep;")();
const carve = new Function(fs.readFileSync("carve.js", "utf8").replace("export function", "function") + "return carve;")();
let level = carve(7, 0, 45), built = 0, next = null;
let s = { t: 0, depth: 0, miner: { x: -1, y: -1 }, start: [-1, -1], cleared: false };
for (let k = 0; k <= 45; k++) {
  if (next !== null) { level = carve(7, next, 45); built = next; console.log(`tick ${k}: cave depth ${next}`, level.start, level.exit); next = null; }
  const right = k >= 1 && k / 30 < 0.25;
  const before = s.depth;
  s = step(s, { dt: 1 / 30, inputs: { start: [level.start.x, level.start.y], exit: [level.exit.x, level.exit.y] }, controls: { pad: { right } }, kernels: { control: (m, p) => { m.dx = p.right ? 1 : 0; } } });
  if (k <= 12 || s.depth !== before) console.log(`tick ${k} x=${s.miner.x} depth=${s.depth}`);
  if (k && k % 3 === 0 && s.depth !== built) next = s.depth;
}
console.log("final", s.depth, s.miner, "same grid at 45 and 46:", JSON.stringify(carve(7, 3, 45)) === JSON.stringify(carve(7, 3, 46)));
EOF
node sim.tmp.cjs
